function historyFile(h,format){
 const parts=h.shown.split(';'),root=parts[0],variant=root.split('~')[0];
 const result=h.result.startsWith('1–0')?'WhiteWins':h.result.startsWith('0–1')?'BlackWins':h.result.startsWith('½')?'Draw':(['WhiteWins','BlackWins','Draw'].includes(parts[1])?parts[1]:'*');
 if(format==='pgn'){
  const tag=(k,v)=>`[${k} "${String(v).replace(/["\\\r\n]/g,' ')}"]`;
  const tags=[tag('GameType',variant),tag('Site','FoulBrood'),tag('Result',result),tag('Notation',h.notation==='analytic'?'Analytic':'Traditional')];
  h.players.forEach((p,i)=>{if(p)tags.push(tag(i?'Black':'White',p))});
  if(h.setupPlaced)tags.push(tag('FoulBroodPlaced',h.setupPlaced));
  if(root.includes('~'))tags.push(`[FoulBroodRoot "${root}"]`);
  if(h.notation==='analytic')tags.push(tag('FoulBroodReplay',btoa(h.game)));
  return tags.join('\n')+'\n\n'+h.moves.map((m,i)=>`${i+1}. ${m}`).join('\n')+'\n\n'+result+'\n';
 }
 let data;
 if(h.notation==='analytic')data={format:'foulbrood-analytic-history',version:1,notation:'Analytic',moves:h.moves,replay_game:h.game,result};
 else if(root.includes('~'))data={format:'foulbrood-position',version:1,root,moves:h.moves,result};
 else {const nodes=[{id:0,parent:null,children:h.moves.length?[1]:[],move_delta:null,position_hash:null}];h.moves.forEach((m,i)=>{const [piece,...position]=m.split(/\s+/),n=i+1;nodes.push({id:n,parent:n-1,children:n<h.moves.length?[n+1]:[],move_delta:{turn:n,piece,position:position.join(' ')},position_hash:null})});data={format:'hive-analysis',version:1,game_type:variant==='Base'?'Base':variant.replace('Base+',''),root_id:0,selected_node_id:h.moves.length,nodes,annotations:{},start_hop:null,result};}
 if(h.setupPlaced)data.setup_placed=h.setupPlaced;data.players={white:h.players[0]||null,black:h.players[1]||null};return JSON.stringify(data,null,2)+'\n';
}
async function exportHistory(format){try{const h=visibleHistory(),text=historyFile(h,format);const url=URL.createObjectURL(new Blob([text],{type:format==='pgn'?'application/x-chess-pgn':'application/json'}));const link=document.createElement('a');link.href=url;link.download=`FoulBrood-${h.notation}.${format}`;document.body.append(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(url),60000)}catch(e){toast(e.message)}}

