function syncAutomaticPreview(){
 const context=state.mode+'|'+state.game+'|'+state.analysis_engine;
 if(context!==suggestionPreviewContext||!state.hints){if(pendingMove?.suggestion){pendingMove=null;lastBoardKey='';}suggestionPreviewContext=context;suggestionPreviewDismissed=false;}
 if(!state.hints){if(pendingMove?.suggestion){pendingMove=null;lastBoardKey='';}return;}
 if(suggestionPreviewDismissed||(pendingMove&&!pendingMove.suggestion)||pendingMove?.confirming||selected||pieceDrag||editorDraft||state.game_review||!canMove())return;
 const move=state.legal.find(m=>m.move===state.hint?.move&&m.to);
 if(move&&pendingMove?.move!==move.move){pendingMove={...move,suggestion:true};lastBoardKey='';}
 else if(!move&&pendingMove?.suggestion){pendingMove=null;lastBoardKey='';}
}
